document.addEventListener('click',e=>{if(e.detail===0)return;const done=completedButtonTouches.get(e.pointerId);if(done&&performance.now()-done.time<1000&&Math.hypot(e.clientX-done.x,e.clientY-done.y)<8){e.preventDefault();e.stopImmediatePropagation()}},true);
$('disconnectWire').onclick=disconnectSelected;
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.target.isContentEditable||e.ctrlKey||e.metaKey)return;if(e.key.toLowerCase()==='r'&&selected&&!selected.startsWith('w')){e.preventDefault();rotatePart(selected)}if(['Delete','Backspace'].includes(e.key)&&selected?.startsWith('w')){e.preventDefault();disconnectSelected()}});
for(const [toggle,dialog,close]of [['helpToggle','help','closeHelp'],['aboutToggle','about','closeAbout']]){$(toggle).onclick=()=>$(dialog).showModal();$(close).onclick=()=>$(dialog).close()}$('closeMeter').onclick=()=>$('meterDialog').close();
let resizePending=false;new ResizeObserver(()=>{if(resizePending)return;resizePending=true;requestAnimationFrame(()=>{resizePending=false;const previous=world.portrait;geometry();if(previous!==world.portrait){view={x:0,y:0,scale:1};parts.filter(p=>p.user||meter(p)).forEach(clampPart)}render()})}).observe($('viewport'));
preset('simple',false);history=[];$('undo').disabled=true;requestAnimationFrame(animate);

$('symbols').onclick=()=>{schematic=!schematic;$('symbols').textContent=schematic?'一般圖示':'電路圖示';$('symbols').setAttribute('aria-pressed',String(schematic));render()};
